/*
 * @generated by sayagi-build — do not edit by hand.
 * Regenerated from Sayagi.toml on every build (`cargo build` / `sayagi pwa`).
 *
 * Service worker ini memakai Workbox (runtime MIT yang di-vendor, lihat
 * `crates/sayagi-build/vendor/workbox`) supaya strateginya deklaratif dan
 * penanganan precache tidak perlu ditulis ulang:
 *   - Precaching  : entri dari `[pwa] precache`, revisinya ikut versi build.
 *   - Navigasi    : network-first, fallback cache, terakhir halaman offline.
 *   - /api/       : network-first (data segar, fallback cache).
 *   - /pkg/       : network-first supaya wasm lama tidak pernah dipasangkan
 *                   dengan HTML baru (nama berkas bundle tidak di-hash).
 *   - Ikon + aset : stale-while-revalidate (tampil seketika, refresh diam-diam).
 *   - URL lain    : langsung ke jaringan (tidak di-cache tanpa aturan).
 *
 * Shell aplikasi (`/pkg/…` beserta potongan `snippets/`) dipanaskan ke cache
 * runtime saat install: halaman offline tidak berguna tanpa Wasm-nya.
 */
importScripts("__WORKBOX_LOADER__");
workbox.setConfig({ modulePathPrefix: "__WORKBOX_PREFIX__" });

const { clientsClaim, skipWaiting } = workbox.core;
const { registerRoute, setCatchHandler } = workbox.routing;
const { NetworkFirst, StaleWhileRevalidate } = workbox.strategies;
const { ExpirationPlugin } = workbox.expiration;
const { CacheableResponsePlugin } = workbox.cacheableResponse;

const VERSION = "__VERSION__";
const RUNTIME_CACHE = `${VERSION}-runtime`;
// Halaman offline punya cache sendiri: entri runtime bisa dibersihkan
// ExpirationPlugin, sedangkan fallback offline harus selalu tersedia.
const OFFLINE_CACHE = `${VERSION}-offline`;
const PRECACHE_ENTRIES = __PRECACHE__;
// Berkas bundle shell (js/wasm/css) dari metadata Leptos; potongan `snippets/`
// yang di-import oleh berkas JS ditemukan saat install.
const SHELL_ASSETS = __SHELL_ASSETS__;
const OFFLINE_URL = __OFFLINE_URL__;
const NETWORK_FIRST = __NETWORK_FIRST__;
const STALE_WHILE_REVALIDATE = __STALE_WHILE_REVALIDATE__;
const MAX_ENTRIES = __MAX_ENTRIES__;
const MAX_AGE_SECONDS = __MAX_AGE_SECONDS__;

const matchesAny = (patterns, url) => patterns.some((pattern) => pattern.test(url.pathname));

const runtimePlugins = () => [
  new CacheableResponsePlugin({ statuses: [0, 200] }),
  new ExpirationPlugin({
    maxEntries: MAX_ENTRIES,
    maxAgeSeconds: MAX_AGE_SECONDS,
    purgeOnQuotaError: true,
  }),
];

skipWaiting();
clientsClaim();

workbox.precaching.precacheAndRoute(PRECACHE_ENTRIES);
workbox.precaching.cleanupOutdatedCaches();

// Precache hanya membersihkan cache bawaannya sendiri; cache runtime yang
// memakai versi lama dibersihkan di sini.
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith("sayagi-") && !key.startsWith(VERSION))
          .map((key) => caches.delete(key))
      );
    })()
  );
});

self.addEventListener("message", (event) => {
  const data = event.data;
  if (data === "SKIP_WAITING") {
    self.skipWaiting();
    return;
  }
  if (data && data.type === "sayagi:warm-document" && typeof data.url === "string") {
    event.waitUntil(warmDocument(data.url));
  }
});

// Menyimpan dokumen rute yang sedang dibuka ke cache runtime.
//
// Router klien tidak pernah meminta dokumen saat berpindah halaman, sehingga
// rute yang dikunjungi tidak masuk cache sendiri; akibatnya reload offline
// hanya menemukan halaman offline. Sekali per versi cache sudah cukup.
async function warmDocument(url) {
  try {
    const cache = await caches.open(RUNTIME_CACHE);
    if (await cache.match(url)) {
      return;
    }
    const response = await fetch(new Request(url, { cache: "reload" }));
    if (response.ok) {
      await cache.put(url, response);
    }
  } catch (error) {
    /* sedang offline saat pemanasan: tidak masalah */
  }
}

// Menyimpan halaman fallback (agar navigasi offline tetap punya jawaban) dan
// memanaskan shell aplikasi ke cache runtime.
self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      if (OFFLINE_URL) {
        try {
          const cache = await caches.open(OFFLINE_CACHE);
          await cache.add(new Request(OFFLINE_URL, { cache: "reload" }));
        } catch (error) {
          console.warn("[sayagi:sw] gagal menyimpan halaman offline:", error);
        }
      }
      await warmShell();
    })()
  );
});

// Potongan `snippets/*` hanya diketahui dari impor di dalam berkas JS, jadi
// daftarnya dibaca dari sana. Setiap kegagalan diabaikan: install tidak boleh
// batal hanya karena satu berkas tidak bisa diambil.
async function warmShell() {
  if (SHELL_ASSETS.length === 0) {
    return;
  }
  let cache;
  try {
    cache = await caches.open(RUNTIME_CACHE);
  } catch (error) {
    return;
  }

  for (const url of SHELL_ASSETS) {
    try {
      const response = await fetch(new Request(url, { cache: "reload" }));
      if (!response.ok) {
        continue;
      }
      if (url.endsWith(".js")) {
        const source = await response.clone().text();
        for (const match of source.matchAll(/from\s*["']\.\/([^"']+)["']/g)) {
          const dependency = new URL(match[1], new URL(url, self.location.origin));
          try {
            const asset = await fetch(new Request(dependency, { cache: "reload" }));
            if (asset.ok) {
              await cache.put(dependency, asset);
            }
          } catch (error) {
            /* berkas opsional */
          }
        }
      }
      await cache.put(url, response);
    } catch (error) {
      console.warn("[sayagi:sw] gagal memanaskan shell:", url, error);
    }
  }
}

registerRoute(
  ({ request }) => request.mode === "navigate",
  new NetworkFirst({
    cacheName: RUNTIME_CACHE,
    plugins: [new CacheableResponsePlugin({ statuses: [0, 200] })],
  })
);

registerRoute(
  ({ url }) => matchesAny(NETWORK_FIRST, url),
  new NetworkFirst({ cacheName: RUNTIME_CACHE, plugins: runtimePlugins() })
);

registerRoute(
  ({ url }) => matchesAny(STALE_WHILE_REVALIDATE, url),
  new StaleWhileRevalidate({ cacheName: RUNTIME_CACHE, plugins: runtimePlugins() })
);

// Dipakai Workbox saat semua route di atas gagal (mis. perangkat offline).
setCatchHandler(async ({ request }) => {
  if (request.destination === "document") {
    if (OFFLINE_URL) {
      const offline = await caches.match(OFFLINE_URL);
      if (offline) {
        return offline;
      }
    }
    const shell = await caches.match("/");
    if (shell) {
      return shell;
    }
  }
  return Response.error();
});
